const MS_PER_DAY = 86400000;
const DATE_PATTERN = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;

function parseDate(value) {
  if (
    typeof value !== "string" ||
    value.length !== 10 ||
    !DATE_PATTERN.test(value)
  ) {
    throw new RangeError("Expected a real calendar date in YYYY-MM-DD form.");
  }

  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(5, 7));
  const day = Number(value.slice(8, 10));

  // UTC setters avoid timezone effects and Date.UTC's special handling of 0–99.
  const parsed = new Date(0);
  parsed.setUTCFullYear(year, month - 1, day);

  if (
    parsed.getUTCFullYear() !== year ||
    parsed.getUTCMonth() !== month - 1 ||
    parsed.getUTCDate() !== day
  ) {
    throw new RangeError("Expected a real calendar date in YYYY-MM-DD form.");
  }

  return parsed.getTime() / MS_PER_DAY;
}

const MIN_DAY = parseDate("0000-01-01");
const MAX_DAY = parseDate("9999-12-31");

function formatDate(day) {
  const date = new Date(day * MS_PER_DAY);

  return [
    String(date.getUTCFullYear()).padStart(4, "0"),
    String(date.getUTCMonth() + 1).padStart(2, "0"),
    String(date.getUTCDate()).padStart(2, "0"),
  ].join("-");
}

function dayOfWeek(day) {
  // Epoch day 0 (1970-01-01) was Thursday. Sunday is 0.
  return ((day + 4) % 7 + 7) % 7;
}

function isWeekday(day) {
  const weekday = dayOfWeek(day);
  return weekday >= 1 && weekday <= 5;
}

function lowerBound(sorted, target) {
  let low = 0;
  let high = sorted.length;

  while (low < high) {
    const middle = low + Math.floor((high - low) / 2);
    if (sorted[middle] < target) {
      low = middle + 1;
    } else {
      high = middle;
    }
  }

  return low;
}

function buildObservedHolidays(holidays) {
  if (!Array.isArray(holidays)) {
    throw new RangeError("holidays must be an array of YYYY-MM-DD dates.");
  }

  const observed = new Set();
  const weekends = [];

  // Reserve every weekday holiday before placing any weekend holiday.
  for (const holiday of holidays) {
    const day = parseDate(holiday);
    if (isWeekday(day)) {
      observed.add(day);
    } else {
      weekends.push(day);
    }
  }

  weekends.sort((a, b) => a - b);

  let nextCandidate = -Infinity;

  for (const holiday of weekends) {
    const nextMonday = holiday + (dayOfWeek(holiday) === 6 ? 2 : 1);
    let candidate = Math.max(nextMonday, nextCandidate);

    while (!isWeekday(candidate) || observed.has(candidate)) {
      candidate += 1;
    }

    observed.add(candidate);

    // Sorted weekend dates have nondecreasing next Mondays, so all earlier
    // candidate weekdays are already occupied and need not be checked again.
    nextCandidate = candidate + 1;
  }

  return Array.from(observed).sort((a, b) => a - b);
}

function isBusinessDayNumber(day, observed) {
  return isWeekday(day) && observed[lowerBound(observed, day)] !== day;
}

function countBusinessDays(first, last, observed) {
  if (first > last) {
    return 0;
  }

  const length = last - first + 1;
  const wholeWeeks = Math.floor(length / 7);
  let count = wholeWeeks * 5;

  for (let day = first + wholeWeeks * 7; day <= last; day += 1) {
    if (isWeekday(day)) {
      count += 1;
    }
  }

  const holidayCount =
    lowerBound(observed, last + 1) - lowerBound(observed, first);

  return count - holidayCount;
}

export function isBusinessDay(date, holidays = []) {
  const day = parseDate(date);
  const observed = buildObservedHolidays(holidays);
  return isBusinessDayNumber(day, observed);
}

export function addBusinessDays(date, n, holidays = []) {
  const start = parseDate(date);

  if (!Number.isInteger(n)) {
    throw new RangeError("n must be an integer.");
  }

  const observed = buildObservedHolidays(holidays);

  if (n === 0) {
    if (isBusinessDayNumber(start, observed)) {
      return date;
    }
    n = 1;
  }

  if (n > 0) {
    const first = start + 1;

    if (countBusinessDays(first, MAX_DAY, observed) < n) {
      throw new RangeError("Result date is outside the YYYY-MM-DD range.");
    }

    let low = first;
    let high = MAX_DAY;

    // Find the first date on which the forward count reaches n.
    while (low < high) {
      const middle = low + Math.floor((high - low) / 2);
      if (countBusinessDays(first, middle, observed) >= n) {
        high = middle;
      } else {
        low = middle + 1;
      }
    }

    return formatDate(low);
  }

  const needed = -n;
  const last = start - 1;

  if (countBusinessDays(MIN_DAY, last, observed) < needed) {
    throw new RangeError("Result date is outside the YYYY-MM-DD range.");
  }

  let low = MIN_DAY;
  let high = last;

  // Moving backwards includes the result date but excludes the start date.
  while (low < high) {
    const middle = low + Math.ceil((high - low) / 2);
    if (countBusinessDays(middle, last, observed) >= needed) {
      low = middle;
    } else {
      high = middle - 1;
    }
  }

  return formatDate(low);
}

export function businessDaysBetween(start, end, holidays = []) {
  const startDay = parseDate(start);
  const endDay = parseDate(end);
  const observed = buildObservedHolidays(holidays);

  const count = countBusinessDays(
    Math.min(startDay, endDay) + 1,
    Math.max(startDay, endDay),
    observed
  );

  // Normalize empty reverse intervals to 0 rather than -0.
  return startDay > endDay && count !== 0 ? -count : count;
}
